package br.com.admeclesial.domain.matrimonio;
import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.domain.pessoa.Pessoa; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="processo_matrimonial",schema="adm_eclesial") public class ProcessoMatrimonial { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organizacao_eclesial_id") OrganizacaoEclesial organizacao; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="nubente_1_id") Pessoa nubente1; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="nubente_2_id") Pessoa nubente2; @Column(name="data_abertura",nullable=false) LocalDate dataAbertura; @Column(name="data_encerramento") LocalDate dataEncerramento; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) StatusProcessoMatrimonial status=StatusProcessoMatrimonial.ABERTO; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public OrganizacaoEclesial getOrganizacao(){return organizacao;} public Pessoa getNubente1(){return nubente1;} public Pessoa getNubente2(){return nubente2;} public LocalDate getDataAbertura(){return dataAbertura;} public LocalDate getDataEncerramento(){return dataEncerramento;} public StatusProcessoMatrimonial getStatus(){return status;} public String getObservacao(){return observacao;} public void setOrganizacao(OrganizacaoEclesial v){organizacao=v;} public void setNubente1(Pessoa v){nubente1=v;} public void setNubente2(Pessoa v){nubente2=v;} public void setDataAbertura(LocalDate v){dataAbertura=v;} public void setDataEncerramento(LocalDate v){dataEncerramento=v;} public void setStatus(StatusProcessoMatrimonial v){status=v;} public void setObservacao(String v){observacao=v;} }